solve(poolDelta float, parks []*park, parkWeightProvider func(park)->float) -> parks []*park {

    remainingPoolDelta = poolDelta
    remainingParks = &parks

    while (remainingPoolDelta > 0 || count(remainingParks) > 0) {

        // calculate park deltas
        desiredParkDeltas map[park] -> float
        for park in remainingParks {
            normalizedParkWeight = parkWeightProvider(park)
            desiredParkDeltas[park] = remainingPoolDelta * normalizedParkWeight
        }

        // apply park detlas and calucate remaining problem
        for park in remainingParks {
            desiredParkDelta = desiredParkDeltas[park]
            actuallyAppliedParkDelta = park.applyDeltaAsBestAsPossible(desiredParkDeltas[park])
            park.adjustOperatingPoint(actuallyAppliedParkDelta)

            remainingPoolDelta = remainingPoolDelta - actuallyAppliedParkDelta

            if desiredParkDelta != actuallyAppliedParkDelta {
                remainingParks.remove(park) //remove saturated park, or park with funky powerlevels.
            }
        }
    }

    return parks // parks carry their cumulated park deltas through something like park.Delta()
}

molProvider interface {
  getParks(parks []Park) returns (orderedParks []Park; minUseParks int)
}


usedParksCount int = 0
moreParksUsedAt time
timeout duration = minute // Arbitrary timeout to avoid toggling


solve(parks []Parks) returns (solvedParks []Parks) {
  if moreParksUsedAt - now() > timeout {
    usedParksCount = 0
  }

  (allParksToSolve, minUseParks) := molProvider.getParks(parks)
  usedParksCount := max(minUseParks, usedParksCount)

  while abs(remainingPoolDeltaToDistribute) > 0 {
    remainingPoolDeltaToDistribute = solveWeighted(allParksToSolve[0:usedParksCount])
    usedParksCount++
  }

  if usedParksCount > minUseParks {
    moreParksUsedAt = now()
  }

  return allParksToSolve
}
